MERGE `{{params.project_name}}.semantics_central.Documents` final
USING (
{{range_query}}
) staging
ON final.document_id = staging.document_id
WHEN MATCHED THEN
UPDATE SET
final.reference_id = staging.reference_id,
final.document_comment = staging.document_comment,
final.file_id = staging.file_id,
final.file_type = staging.file_type,
final.document_category = staging.document_category,
final.document_visibility = staging.document_visibility,
final.document_entity = staging.document_entity,
final.uploader = staging.uploader,
final.modified_by = staging.modified_by,
final.file_name = staging.file_name,
final.file_size = staging.file_size,
final.created_at = staging.created_at,
final.updated_at = staging.updated_at,
final.deleted_at = staging.deleted_at,
final.document_status = staging.document_status,
final.created_by = staging.created_by,
final.created_by_name = staging.created_by_name,
final.updated_by = staging.updated_by,
final.updated_by_name = staging.updated_by_name,
final.deleted_by = staging.deleted_by,
final.deleted_by_name = staging.deleted_by_name,
final.print_reference_id = staging.print_reference_id,
final.is_public = staging.is_public,
final.country_id = staging.country_id
WHEN NOT MATCHED THEN
INSERT (
document_id,
reference_id,
document_comment,
file_id,
file_type,
document_category,
document_visibility,
document_entity,
uploader,
modified_by,
file_name,
file_size,
created_at,
updated_at,
deleted_at,
document_status,
created_by,
created_by_name,
updated_by,
updated_by_name,
deleted_by,
deleted_by_name,
print_reference_id,
is_public,
country_id
) VALUES (
staging.document_id,
staging.reference_id,
staging.document_comment,
staging.file_id,
staging.file_type,
staging.document_category,
staging.document_visibility,
staging.document_entity,
staging.uploader,
staging.modified_by,
staging.file_name,
staging.file_size,
staging.created_at,
staging.updated_at,
staging.deleted_at,
staging.document_status,
staging.created_by,
staging.created_by_name,
staging.updated_by,
staging.updated_by_name,
staging.deleted_by,
staging.deleted_by_name,
staging.print_reference_id,
staging.is_public,
staging.country_id
)